## Manifest 完整接口定义

以下 JSON 与插件包内实际 `manifest.json` 逐字段一致，覆盖插件身份、权限、配置、鉴权、参数、校验、创建、Agent、查询、取消、结果下载、响应和 Agent 响应映射。`documentation` 字段的值就是当前完整文档；为避免文档在自身内部无限递归，JSON 中仅用等义占位文本表示正文。

```json
{
  "apiVersion": "beeftv.plugin/v2",
  "id": "tencent-hunyuan-image-35",
  "name": "腾讯混元生图 3.5",
  "version": "1.0.0",
  "author": "BeefTV Contributors",
  "description": "腾讯云 TokenHub 混元生图 3.5 请求协议插件。",
  "documentation": "<当前插件的完整 documentation，由 README.md 与 docs/interface.md 拼接而成；为避免 JSON 递归，此处不重复展开正文。>",
  "permissions": [
    "generation.run",
    "media.read"
  ],
  "configuration": {
    "fields": [
      {
        "name": "apiKey",
        "type": "secret",
        "label": "API Key",
        "required": true
      }
    ]
  },
  "contributes": {
    "providers": [
      {
        "id": "tencent-hunyuan-image-35",
        "label": "腾讯混元生图 3.5",
        "capabilities": [
          "image"
        ],
        "scopes": [
          "admin.system-channel",
          "user.custom-channel",
          "canvas",
          "creation",
          "agent"
        ],
        "baseUrl": "https://tokenhub.tencentmaas.com",
        "requiresPublicMediaUrls": false,
        "auth": {
          "type": "bearer",
          "field": "apiKey"
        },
        "parameters": [
          {
            "name": "model",
            "type": "string",
            "required": true,
            "mapping": "model",
            "description": "图片模型 ID。"
          },
          {
            "name": "prompt",
            "type": "string",
            "required": true,
            "mapping": "prompt",
            "description": "图片提示词。"
          },
          {
            "name": "images",
            "type": "media[]",
            "required": false,
            "mapping": "provider image/reference fields",
            "description": "参考图或编辑源图，role 由业务层确定。"
          },
          {
            "name": "aspectRatio",
            "type": "string",
            "required": false,
            "mapping": "size/aspect_ratio",
            "description": "比例或尺寸，语义按协议说明。"
          },
          {
            "name": "providerOptions",
            "type": "object",
            "required": false,
            "mapping": "provider-specific fields",
            "description": "插件命名空间内的厂商扩展字段。"
          }
        ],
        "create": {
          "method": "POST",
          "path": "/v1/wand/hunyuan-image/v35-generation",
          "contentType": "application/json",
          "body": {
            "model": {
              "$ref": "request.model"
            },
            "messages": [
              {
                "role": "user",
                "content": {
                  "$concatArrays": [
                    [
                      {
                        "type": "text",
                        "text": {
                          "$ref": "request.prompt"
                        }
                      }
                    ],
                    {
                      "$map": {
                        "from": {
                          "$sortByOrder": {
                            "$ref": "request.images"
                          }
                        },
                        "as": "media",
                        "in": {
                          "type": "image_url",
                          "image_url": {
                            "url": {
                              "$coalesce": [
                                {
                                  "$ref": "media.dataUrl"
                                },
                                {
                                  "$ref": "media.url"
                                }
                              ]
                            }
                          }
                        }
                      }
                    }
                  ]
                }
              }
            ],
            "size": {
              "$omitEmpty": {
                "$switch": {
                  "cases": [
                    {
                      "when": {
                        "$eq": [
                          {
                            "$len": {
                              "$split": [
                                {
                                  "$trim": {
                                    "$ref": "request.aspectRatio"
                                  }
                                },
                                "x"
                              ]
                            }
                          },
                          2
                        ]
                      },
                      "then": {
                        "$trim": {
                          "$ref": "request.aspectRatio"
                        }
                      }
                    }
                  ],
                  "default": {
                    "$switch": {
                      "cases": [
                        {
                          "when": {
                            "$eq": [
                              {
                                "$trim": {
                                  "$ref": "request.aspectRatio"
                                }
                              },
                              "1:1"
                            ]
                          },
                          "then": "1024x1024"
                        },
                        {
                          "when": {
                            "$eq": [
                              {
                                "$trim": {
                                  "$ref": "request.aspectRatio"
                                }
                              },
                              "3:2"
                            ]
                          },
                          "then": "1536x1024"
                        },
                        {
                          "when": {
                            "$eq": [
                              {
                                "$trim": {
                                  "$ref": "request.aspectRatio"
                                }
                              },
                              "2:3"
                            ]
                          },
                          "then": "1024x1536"
                        },
                        {
                          "when": {
                            "$eq": [
                              {
                                "$trim": {
                                  "$ref": "request.aspectRatio"
                                }
                              },
                              "4:3"
                            ]
                          },
                          "then": "1360x1024"
                        },
                        {
                          "when": {
                            "$eq": [
                              {
                                "$trim": {
                                  "$ref": "request.aspectRatio"
                                }
                              },
                              "3:4"
                            ]
                          },
                          "then": "1024x1360"
                        },
                        {
                          "when": {
                            "$eq": [
                              {
                                "$trim": {
                                  "$ref": "request.aspectRatio"
                                }
                              },
                              "16:9"
                            ]
                          },
                          "then": "1824x1024"
                        },
                        {
                          "when": {
                            "$eq": [
                              {
                                "$trim": {
                                  "$ref": "request.aspectRatio"
                                }
                              },
                              "9:16"
                            ]
                          },
                          "then": "1024x1824"
                        },
                        {
                          "when": {
                            "$eq": [
                              {
                                "$trim": {
                                  "$ref": "request.aspectRatio"
                                }
                              },
                              "21:9"
                            ]
                          },
                          "then": "2048x878"
                        }
                      ],
                      "default": null
                    }
                  }
                }
              }
            },
            "session": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.tencent-hunyuan-image-35.session"
              }
            },
            "seed": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.tencent-hunyuan-image-35.seed"
              }
            },
            "footnote": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.tencent-hunyuan-image-35.footnote"
              }
            },
            "generate_max_pixels": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.tencent-hunyuan-image-35.generate_max_pixels"
              }
            },
            "resize_max_pixels": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.tencent-hunyuan-image-35.resize_max_pixels"
              }
            }
          }
        },
        "response": {
          "taskId": {
            "$coalesce": [
              {
                "$ref": "response.id"
              }
            ]
          },
          "status": "succeeded",
          "message": {
            "$coalesce": [
              {
                "$ref": "response.error.message"
              },
              {
                "$ref": "response.message"
              }
            ]
          },
          "images": {
            "$map": {
              "from": {
                "$ref": "response.choices"
              },
              "as": "choice",
              "in": {
                "url": {
                  "$omitEmpty": {
                    "$ref": "choice.delta.image.url"
                  }
                }
              }
            }
          },
          "usage": {
            "$coalesce": [
              {
                "$ref": "response.usage"
              },
              {
                "$ref": "response.tokenhub_usage"
              }
            ]
          },
          "errorPaths": [
            "error.code"
          ],
          "messagePaths": [
            "error.message"
          ],
          "resultEphemeral": true
        }
      }
    ]
  }
}
```
